<h2 class="section-title mb">Arsip Setlist</h2><?php foreach($groups as $g): ?><details class="setlist"><summary class="setlist-head"><span><?= e($g['title']) ?></span></summary><div class="setlist-body grid-2"><div><p class="label-merah">Set Utama</p><ol class="tracklist"><?php foreach($g['main'] as $track): ?><li><?= e($track['title']) ?></li><?php endforeach; ?></ol></div><div><p class="label-merah">Encore</p><ul class="tracklist"><?php foreach($g['encore'] as $track): ?><li><?= (int)$track['position'] ?>. <?= e($track['title']) ?></li><?php endforeach; ?></ul><p><?= e($g['venue']??'') ?> · <?= e(tanggal_id($g['start_at'])) ?></p></div></div></details><?php endforeach; ?><?php if(!$groups): ?><p>Belum ada arsip setlist.</p><?php endif; ?>
